import{_ as o,o as t,c as d,a3 as n}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"PGO","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"PGO | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/pgo"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/pgo"}]]},"headers":[],"relativePath":"xclang/design/pgo.md","filePath":"en/xclang/design/pgo.md","lastUpdated":1794509097000}'),c={name:"xclang/design/pgo.md"};function a(i,e,r,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="pgo" tabindex="-1">PGO <a class="header-anchor" href="#pgo" aria-label="Permalink to &quot;PGO&quot;">​</a></h1><p>xclang&#39;s <code>clang</code> and <code>lld</code> are built with profile-guided optimization (PGO) and ThinLTO on all six hosts from a single frontend profile recorded on Linux x64. On C++ benchmarks in 23.1.2.6, xclang compiles as fast as LLVM&#39;s own PGO+ThinLTO release builds on Linux and macOS and takes 11 to 22% less time than LLVM&#39;s build on Windows x64; in 23.1.2.1, the profile cut C++ compile times by 16 to 34% compared to the same build without PGO.</p><h2 id="the-training" tabindex="-1">The Training <a class="header-anchor" href="#the-training" aria-label="Permalink to &quot;The Training&quot;">​</a></h2><p>PGO optimizes the compiler and linker for the code paths exercised during training. In <a href="https://github.com/clice-io/xclang/blob/main/toolchain/pgo/train.ts" target="_blank" rel="noreferrer"><code>toolchain/pgo/train.ts</code></a>, an instrumented Linux x64 build of <code>clang</code>, <code>clang-scan-deps</code> and <code>lld</code> runs workloads matching both build systems and language servers:</p><ul><li><strong>C and C++ compiles</strong>: Abseil (<code>-std=c++20</code>) and SQLite (<code>sqlite3.c</code>, <code>shell.c</code>) at <code>-O0 -g</code> and <code>-O2</code> for <code>x86_64</code> and <code>aarch64</code> Linux, plus SQLite with <code>-O2 -flto=thin</code> for both Linux targets and at <code>-O0 -g</code> and <code>-O2</code> for <code>x86_64-w64-mingw32</code>.</li><li><strong>Precompiled headers and editor preambles</strong>: one shared precompiled header consumed at <code>-O0 -g</code>, <code>-O2</code> and <code>-fsyntax-only</code> with code completion on <code>absl::</code>, and a preamble extracted from the leading <code>#include</code> block of each Abseil source file, precompiled once per file and used to parse the body and run code completion (<code>std::</code>, <code>absl::</code>) as an editor does.</li><li><strong>C++20 modules and P1689 scanning</strong>: <code>libc++</code>&#39;s <code>std</code> and <code>std.compat</code>, <code>magic_enum</code>, <code>Vulkan-Hpp</code> (<code>vulkan.cppm</code> and <code>vulkan_video.cppm</code> on <code>x86_64</code>), a wrapped <code>nlohmann/json</code> module, a multi-partition <code>geometry</code> module (<code>shapes</code>, <code>detail</code>, <code>algorithms</code>), and their importers at <code>-std=c++23</code>. At <code>-O2</code>, modules build in two phases (<code>--precompile</code> to <code>.pcm</code>, then <code>.pcm</code> to <code>.o</code>); at <code>-O0 -g</code>, in one phase with reduced module files (<code>-fmodules-reduced-bmi -fmodule-output=</code>). <code>clang-scan-deps -format=p1689</code> scans individual compile commands (as CMake runs it) and a whole <code>compile_commands.json</code> database for Abseil.</li><li><strong>Code completion</strong>: <code>-fsyntax-only -Xclang -code-completion-at=...</code> across Abseil sources, PCH users, preambles and module importers (<code>std::</code>, <code>nlohmann::</code>, <code>magic_enum::</code>, <code>geometry::</code>, <code>vk::</code>, <code>j.</code>).</li><li><strong>Linking</strong>: ELF links (at <code>-O0 -g</code>, <code>-O2</code>, and <code>-O2 -flto=thin</code> for <code>x86_64</code> and <code>aarch64</code> Linux, plus the module programs) and COFF links (<code>x86_64-w64-mingw32</code> SQLite at <code>-O0 -g</code> and <code>-O2</code>) through <code>lld</code>.</li></ul><p>About 1,700 runs in 23 minutes produce one merged profile per release, published as <code>xclang-&lt;version&gt;.profdata</code> (<a href="./../reference/releases#assets">releases</a>).</p><p>The training corpus does not currently include Objective-C, <code>clang-cl</code> and MSVC-mode parsing, Mach-O links (<code>ld64.lld</code>), <code>aarch64</code> COFF links, Windows- or macOS-only host code paths, sanitizer passes, or <code>libclang</code> libraries that <code>clang</code> itself does not call (<code>clang-tidy</code> checks, <code>clangIndex</code>, <code>clangIncludeCleaner</code>). Widening the training corpus to cover those is <a href="./roadmap#pgo-training">planned</a> and happens between releases.</p><h2 id="one-profile-for-every-host" tabindex="-1">One Profile for Every Host <a class="header-anchor" href="#one-profile-for-every-host" aria-label="Permalink to &quot;One Profile for Every Host&quot;">​</a></h2><p><code>clang</code> supports two PGO instrumentation modes, which determine whether a profile recorded on one host can optimize another:</p><ul><li><strong>IR instrumentation</strong> (<code>-fprofile-generate</code>) instruments LLVM IR after early optimization passes and hashes each function&#39;s control-flow graph at that point. Because early passes consult target cost models, the same source function can produce different control-flow graphs on <code>x86_64</code> and <code>arm64</code>, so a profile recorded on one architecture does not match the other.</li><li><strong>Frontend instrumentation</strong> (<code>-fprofile-instr-generate</code>, LLVM&#39;s <code>LLVM_BUILD_INSTRUMENTED=Frontend</code>) instruments the <code>clang</code> AST and hashes each function from its source structure. The same source produces the same hash on every target.</li></ul><p>xclang uses frontend instrumentation. In experiments before 23.1.2.1, a profile recorded on Linux x64 matched all but 0 or 1 of 113,000 functions on each of the six hosts and gave compile times within runner noise of per-host IR profiles merged from all six hosts (compile time of Abseil / LLVM&#39;s <code>Sema</code> relative to no PGO, median of five runners):</p><table tabindex="0"><thead><tr><th>host</th><th>frontend, Linux profile</th><th>IR, six profiles merged</th></tr></thead><tbody><tr><td>Linux x64</td><td>0.725 / 0.727</td><td>0.722 / 0.721</td></tr><tr><td>Linux arm64</td><td>0.814 / 0.800</td><td>0.826 / 0.844</td></tr><tr><td>macOS arm64</td><td>0.905 / 0.818</td><td>0.895 / 0.864</td></tr><tr><td>Windows x64</td><td>0.771 / 0.792</td><td>0.764 / 0.820</td></tr></tbody></table><p>Training therefore runs once on a single Linux x64 runner, and its profile optimizes all six host toolchains and <code>libclang</code> archives without per-host instrumented builds or emulation.</p><h3 id="the-remapping-file" tabindex="-1">The Remapping File <a class="header-anchor" href="#the-remapping-file" aria-label="Permalink to &quot;The Remapping File&quot;">​</a></h3><p>Frontend profiles look up each function by its mangled name, and fixed-width and pointer-sized integer types mangle differently across LP64 and LLP64/Darwin ABIs: <code>size_t</code> and <code>uint64_t</code> are <code>unsigned long</code> (<code>m</code>) on Linux but <code>unsigned long long</code> (<code>y</code>) on Windows (and <code>uint64_t</code> is <code>unsigned long long</code> on macOS), while <code>int64_t</code> is <code>long</code> (<code>l</code>) on Linux and <code>long long</code> (<code>x</code>) on Windows and macOS. Without remapping, functions taking <code>size_t</code> or <code>uint64_t</code> have different mangled names on Windows and macOS than in the Linux profile and receive no profile counts.</p><p><a href="https://github.com/clice-io/xclang/blob/main/toolchain/pgo/remap.txt" target="_blank" rel="noreferrer"><code>toolchain/pgo/remap.txt</code></a> maps <code>type m y</code> and <code>type l x</code> via <code>-fprofile-remapping-file</code>. In the same pre-23.1.2.1 experiments, adding the remapping file improved the Abseil / <code>Sema</code> compile-time ratios on macOS arm64 from <code>0.896 / 0.923</code> to <code>0.794 / 0.845</code> and on Windows x64 from <code>0.787 / 0.824</code> to <code>0.772 / 0.829</code>.</p><p>Two small groups of functions are not matched by LLVM&#39;s remapper:</p><ul><li>On Windows, 230 functions with integer-literal template arguments of those types (1.8% of total counts).</li><li>Functions with internal linkage: 122 on Windows and 39 on macOS (0.06% and 0.02% of total counts), because frontend profile keys for <code>static</code> functions have the form <code>&lt;file&gt;:&lt;mangled&gt;</code> and the remapper does not strip the <code>&lt;file&gt;:</code> prefix before parsing the mangled name.</li></ul><h2 id="what-it-buys" tabindex="-1">What It Buys <a class="header-anchor" href="#what-it-buys" aria-label="Permalink to &quot;What It Buys&quot;">​</a></h2><p><code>bench.yml</code> (<code>tests/bench/bench.ts</code>) measures native compile times on runners of each host using code that is not in the training corpus:</p><ul><li>ten of <code>fmt</code>&#39;s tests (template-heavy C++20);</li><li>the C source files of <code>lua</code>;</li><li>precompiling <code>libc++</code>&#39;s <code>std</code> module.</li></ul><p>Each workload is compiled at <code>-fsyntax-only</code>, <code>-O0 -g</code> and <code>-O2</code>, one file at a time. Rounds interleave the compilers in rotating order on the same runner, taking the median across rounds on each machine and then the median of each machine&#39;s ratio to the reference across runners. Differences of a few percent are within runner noise.</p><p>The reference compiler is LLVM&#39;s official release build of the same version: built with PGO and ThinLTO on Linux and macOS (plus BOLT on Linux x64; BOLT for xclang&#39;s Linux hosts is <a href="./roadmap#bolt">in research</a>), and with PGO without LTO on Windows. Because LLVM publishes no <code>x86_64</code> macOS binary, xclang itself is the reference on <code>x86_64</code> macOS.</p><h3 id="_23-1-2-6" tabindex="-1">23.1.2.6 <a class="header-anchor" href="#_23-1-2-6" aria-label="Permalink to &quot;23.1.2.6&quot;">​</a></h3><p>Compile time relative to LLVM 23.1.2&#39;s release build, median of five runners per host, 2026-10-06 (<a href="https://github.com/clice-io/xclang/actions/runs/37356476645" target="_blank" rel="noreferrer">run 37356476645</a>, measuring the published 23.1.2.6 archives; Linux x64 has four runners because one job failed while listing sizes before benchmarking). The <code>llvm.exe</code> rows invoke <code>llvm.exe clang++</code> directly without the <code>clang++.exe</code> launcher:</p><table tabindex="0"><thead><tr><th>host</th><th>fmt (syntax / O0 / O2)</th><th>lua (syntax / O0 / O2)</th><th>std (O0 / O2)</th></tr></thead><tbody><tr><td>Linux x64</td><td>1.035 / 1.009 / 1.069</td><td>1.118 / 1.062 / 1.109</td><td>1.013 / 1.022</td></tr><tr><td>Linux arm64</td><td>1.000 / 0.976 / 1.042</td><td>1.082 / 1.011 / 1.075</td><td>0.970 / 0.994</td></tr><tr><td>macOS arm64</td><td>0.902 / 0.935 / 1.014</td><td>1.169 / 0.971 / 0.959</td><td>0.980 / 0.890</td></tr><tr><td>Windows x64</td><td>0.798 / 0.825 / 0.890</td><td>1.083 / 1.050 / 1.001</td><td>0.777 / 0.849</td></tr><tr><td>Windows x64, <code>llvm.exe</code></td><td>0.798 / 0.809 / 0.885</td><td>0.968 / 0.960 / 0.974</td><td>0.821 / 0.844</td></tr><tr><td>Windows arm64</td><td>0.888 / 0.906 / 0.954</td><td>1.271 / 1.212 / 1.167</td><td>0.925 / 0.940</td></tr><tr><td>Windows arm64, <code>llvm.exe</code></td><td>0.860 / 0.898 / 0.947</td><td>1.019 / 1.065 / 1.056</td><td>0.915 / 0.932</td></tr></tbody></table><p>Apple&#39;s <code>clang</code> ran on the same macOS runners: on <code>arm64</code>, relative to LLVM&#39;s build, it took <code>1.097 / 1.207 / 1.206</code> on <code>fmt</code> and <code>0.879 / 0.875 / 1.004</code> on <code>lua</code>; on <code>x86_64</code>, relative to xclang, it took <code>1.168 / 1.223 / 1.221</code> on <code>fmt</code> and <code>0.841 / 0.973 / 0.990</code> on <code>lua</code>.</p><p>Summary of the 23.1.2.6 measurements:</p><ul><li><strong>Linux and macOS</strong>: on C++, xclang matches LLVM&#39;s PGO+ThinLTO builds; on <code>lua</code>&#39;s small C files it takes up to 17% longer. On Linux x64, where LLVM&#39;s binary is also BOLT-optimized, xclang takes up to 7% longer on C++ and 12% longer on C.</li><li><strong>Windows</strong>: compared to LLVM&#39;s MSVC-built <code>clang</code> (PGO without LTO), xclang&#39;s MinGW-built <code>clang</code> (PGO and ThinLTO) takes 11 to 22% less time on C++ on x64 and 5 to 11% less on arm64.</li><li><strong>Windows launcher overhead</strong>: <code>lua</code>&#39;s C files each compile in a few dozen milliseconds, so spawning <code>clang++.exe</code> before <code>llvm.exe</code> adds up to 12% on x64 and 25% on arm64 compared to running <code>llvm.exe clang++</code> directly; on C++ files, the process-start cost is negligible (<a href="./windows#the-launchers">the launchers</a>).</li><li><strong>Apple&#39;s <code>clang</code></strong>: takes 17 to 29% more time than xclang on <code>fmt</code> across both macOS architectures, and between 25% less and 5% more on <code>lua</code>.</li></ul><h3 id="_23-1-2-1" tabindex="-1">23.1.2.1 <a class="header-anchor" href="#_23-1-2-1" aria-label="Permalink to &quot;23.1.2.1&quot;">​</a></h3><p>Compile time relative to LLVM 23.1.2&#39;s release build, median of three runners (<a href="https://github.com/clice-io/xclang/actions/runs/36249036595" target="_blank" rel="noreferrer">run 36249036595</a> for Linux and macOS, <a href="https://github.com/clice-io/xclang/actions/runs/36250216010" target="_blank" rel="noreferrer">run 36250216010</a> for Windows), including the same xclang build compiled without its PGO profile (<code>no PGO, fmt</code>):</p><table tabindex="0"><thead><tr><th>host</th><th>fmt (syntax / O0 / O2)</th><th>lua</th><th>std (O0 / O2)</th><th>no PGO, fmt</th></tr></thead><tbody><tr><td>Linux x64</td><td>1.031 / 1.006 / 1.046</td><td>1.106 / 1.061 / 1.098</td><td>1.047 / 1.022</td><td>1.279 / 1.250 / 1.244</td></tr><tr><td>Linux arm64</td><td>0.972 / 0.957 / 1.018</td><td>1.012 / 0.968 / 1.050</td><td>0.959 / 0.964</td><td>1.283 / 1.237 / 1.272</td></tr><tr><td>macOS arm64</td><td>0.986 / 0.983 / 1.050</td><td>0.948 / 0.804 / 0.994</td><td>0.860 / 0.955</td><td>1.367 / 1.323 / 1.353</td></tr><tr><td>Windows x64</td><td>0.809 / 0.830 / 0.893</td><td>1.075 / 1.049 / 1.041 (<code>llvm.exe</code>: 1.044 / 0.987 / 1.020)</td><td>0.885 / 1.021</td><td>1.226 / 1.155 / 1.227</td></tr><tr><td>Windows arm64</td><td>0.899 / 0.916 / 0.958</td><td>1.332 / 1.238 / 1.187 (<code>llvm.exe</code>: 1.090 / 1.058 / 1.079)</td><td>0.944 / 0.939</td><td>1.178 / 1.150 / 1.162</td></tr></tbody></table><ul><li><strong>Effect of the profile</strong>: without PGO, the same ThinLTO build took 1.15 to 1.37 times as long as LLVM&#39;s release build on <code>fmt</code>; with the Linux frontend profile, compile time dropped by 16 to 34%.</li><li><strong><code>x86_64</code> macOS runner noise</strong>: on <code>macos-15-intel</code>, the noisiest of the six runner types, 23.1.2.1 without PGO measured <code>0.84</code> to <code>1.12</code> relative to xclang with PGO and Apple&#39;s <code>clang</code> measured <code>0.89</code> to <code>1.08</code> on <code>fmt</code> (<code>0.57</code> to <code>0.87</code> on <code>lua</code>), whereas in 23.1.2.6&#39;s five-runner run Apple&#39;s <code>clang</code> was 17 to 22% slower on <code>fmt</code>. Whether PGO helps the cross-compiled <code>x86_64</code> macOS host binary on Intel Macs is not established beyond runner noise.</li></ul>',33)])])}const u=o(c,[["render",a]]);export{p as __pageData,u as default};
